# Ze as the RTR CLIENT of a real StayRTR cache (172.30.0.12:8282).
#
# There is no BGP peer here on purpose. The subject is the RTR half: what Ze
# decodes from another implementation's Prefix PDUs, and whether the VRPs it
# builds from them agree with what that cache meant. A peer would add a second
# daemon and a second protocol between the wire under test and the verdict.
#
# `port 8282` is StayRTR's default RTR port, not Ze's 323 plain-TCP default.
plugin {
	internal bgp-rpki {
		use bgp-rpki;
	}
}
bgp {
	rpki {
		cache-server 172.30.0.12 {
			trusted-network true;
			port 8282;
		}
		validation-timeout 5;
		action {
			invalid reject;
			not-found accept;
		}
	}
}

